package com.wms.entity;
import jakarta.persistence.*;import org.hibernate.annotations.CreationTimestamp;import java.time.Instant;import java.util.*;
@Entity @Table(name="wms_workflow_definition",uniqueConstraints=@UniqueConstraint(name="uk_workflow_business_version",columnNames={"businessType","version"}))
public class WorkflowDefinition{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,length=32)private String businessType;@Column(nullable=false)private Integer version=1;@Column(nullable=false,length=64)private String name;@Column(nullable=false)private boolean enabled=true;@Column(nullable=false,length=16,columnDefinition="varchar(16) not null default 'ALWAYS'")private String triggerMode="ALWAYS";@Column(length=1000)private String triggerCategories;private Integer minTotalQty;@Column(precision=18,scale=2)private java.math.BigDecimal minTotalAmount;@CreationTimestamp@Column(updatable=false)private Instant publishedAt;@OneToMany(mappedBy="definition",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER)@OrderBy("sequence asc")private List<WorkflowNode> nodes=new ArrayList<>();public Long getId(){return id;}public String getBusinessType(){return businessType;}public void setBusinessType(String v){businessType=v;}public Integer getVersion(){return version;}public void setVersion(Integer v){version=v;}public String getName(){return name;}public void setName(String v){name=v;}public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public String getTriggerMode(){return triggerMode;}public void setTriggerMode(String v){triggerMode=v;}public String getTriggerCategories(){return triggerCategories;}public void setTriggerCategories(String v){triggerCategories=v;}public Integer getMinTotalQty(){return minTotalQty;}public void setMinTotalQty(Integer v){minTotalQty=v;}public java.math.BigDecimal getMinTotalAmount(){return minTotalAmount;}public void setMinTotalAmount(java.math.BigDecimal v){minTotalAmount=v;}public Instant getPublishedAt(){return publishedAt;}public List<WorkflowNode> getNodes(){return nodes;}}
